function iconFor(n){return L.divIcon({className:'',html:pinHTML(n),iconSize:[58,68],iconAnchor:[29,68]})}
function gmapsDirections(address){return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(address)}`}
// Route-planner meta line for event stops: their date + hours, never a town.
function eventStopDateLine(x){if(x.ongoing)return 'Open all season'+(x.hours?' · '+x.hours:'');const d=x.date||String(x.startAt||'').slice(0,10);return (d?new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}):'Date TBA')+(x.hours?' · '+x.hours:'')}
function isTreatStop(x){return x.kind==='Trick-or-treat stop'}
function eventIsUpcoming(x){return x.ongoing===true||new Date(x.endAt).getTime()>Date.now()}
function matchFilter(x){if(!inCurrentSeason(x))return false;if(x.placeholder)return state.category==='displays'&&state.filter==='All'&&(typeof isDefaultArea!=='function'||!state.search||isDefaultArea(state.search));if(state.category==='events')return false;if(state.dateFilter&&state.dateFilter.kind&&typeof schedulesDateMatch==='function'&&!schedulesDateMatch(x,state.dateFilter))return false;if(state.search&&typeof inSearchArea==='function'&&!inSearchArea(x,state.search))return false;if(isTreatStop(x)!==(state.category==='treats'))return false;if(state.category==='treats')return (state.filter==='All'||x.town===state.filter)&&(!state.categoryFeature||(x.features||[]).includes(state.categoryFeature));if(state.filter==='All')return true;if(['Family Friendly','Spooky','Scary'].includes(state.filter))return x.levels.includes(state.filter);if(['Walk-through','Drive-by','Walk-by'].includes(state.filter))return x.type.includes(state.filter)||(x.type.includes('Drive or walk by (both)')&&['Drive-by','Walk-by'].includes(state.filter));return x.features.some(f=>featureKey(f)===state.filter)}
function matchingEvents(){const dayOf=x=>x.date||String(x.startAt||'').slice(0,10);const filtered=events.filter(x=>eventIsUpcoming(x)&&inCurrentSeason(x)&&(state.filter==='All'||x.eventType===state.filter)&&(!state.categoryFeature||(x.features||[]).includes(state.categoryFeature))&&(!state.eventDay||x.ongoing||dayOf(x)===state.eventDay)&&(!state.search||typeof inSearchArea!=='function'||inSearchArea(x,state.search))&&(x.ongoing||!state.dateFilter||!state.dateFilter.kind||typeof eventDateMatch!=='function'||eventDateMatch(x,state.dateFilter)));return typeof orderByDistance==='function'?orderByDistance(filtered,state.search,(a,b)=>new Date(a.startAt)-new Date(b.startAt)):filtered.sort((a,b)=>new Date(a.startAt)-new Date(b.startAt))}
// Single source of truth for the ordered visible set. Falls back to number
// order during the very first render, before location.js has loaded.
function activeListings(){return typeof visibleSet==='function'?visibleSet({items:listings,search:state.search,predicate:matchFilter,keepUnlocated:true}):listings.filter(matchFilter)}
function distanceLabelHTML(x){if(!state.search||typeof haversineMi!=='function'||typeof formatDistance!=='function'||!Number.isFinite(x.lat)||!Number.isFinite(x.lng))return '';return `<span class="card__distance">${safeListingText(formatDistance(haversineMi(state.search,x)))} mi away</span>`}
function geoEmptyState(){if(!state.search||typeof isDefaultArea!=='function'||typeof nextRadius!=='function'||isDefaultArea(state.search))return null;const r=state.search.radius,next=nextRadius(r);const headline=state.search.mode==='device'?`Nothing within ${r} miles of your location yet.`:state.search.mode==='area'?'Nothing in this map area yet.':`Nothing within ${r} miles of ${state.search.zip} yet.`;return {headline,next}}
function wireEmptyAction(geoEmpty,formUrl){const btn=document.getElementById('emptyActionBtn');if(!btn)return;btn.hidden=false;if(geoEmpty.next){btn.textContent=`Expand to ${geoEmpty.next} miles`;btn.onclick=()=>document.dispatchEvent(new CustomEvent('hf:expand-radius',{detail:{radius:geoEmpty.next}}))}else{btn.textContent='Add a listing in your area';btn.onclick=()=>window.open(formUrl,'_blank','noopener')}}
