function featureKey(value){const f=String(value).trim().toLowerCase().replace(/\s*\/\s*/g,'/');if(f==='live actors')return 'Actors';return Object.keys(FEATURE_ICONS).find(k=>k.toLowerCase().replace(/\s*\/\s*/g,'/')===f)||value}
function featureIcon(value){const item=FEATURE_ICONS[featureKey(value)];return item?`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${item.path}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`:''}
function featureChip(value){const key=featureKey(value),item=FEATURE_ICONS[key];return item?`<span class="chip feature-chip">${featureIcon(key)}<span>${safeListingText(item.label)}</span></span>`:`<span class="chip">${safeListingText(value)}</span>`}
function scarePips(levels){const order=['Family Friendly','Spooky','Scary'];return `<span class="pips">${order.map(x=>`<span class="pip ${levels.includes(x)?'is-on':''}"></span>`).join('')}</span>${safeListingText(levels.length?levels.join(' · '):'Not specified')}`}
function listingStatusHTML(x){if(!['temporarily_closed','weather_cancelled'].includes(x.status))return '';if(x.statusUntil&&new Date(x.statusUntil).getTime()<Date.now())return '';return `<div class="listing-status" role="note"><strong>${x.status==='weather_cancelled'?'Weather cancellation':'Temporarily closed'}</strong>${x.statusNote?`<span>${safeListingText(x.statusNote)}</span>`:''}${x.statusUntil?`<small>Through ${safeListingText(new Date(x.statusUntil).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</small>`:''}<small>Check the host’s updates before visiting.</small></div>`}
function safeListingText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function listingUpdatedHTML(x){if(!x.updatedAt)return '';const date=new Date(x.updatedAt+'T12:00:00');if(Number.isNaN(date.getTime()))return '';return `<p class="listing-updated">Listing updated <time datetime="${safeListingText(x.updatedAt)}">${date.toLocaleDateString(undefined,{dateStyle:'medium'})}</time></p>`}
function compactTime(value){return String(value).replace(/:00/g,'').replace(/(\d+)\s*(AM|PM)–(\d+)\s*\2/g,'$1–$3 $2')}
function treatCardHTML(x){const onRoute=state.route.some(r=>r.num===x.num);return `<article class="card card--compact treat-stop-card ${state.selected===x.num?'is-selected':''}" data-card="${x.num}" tabindex="0" aria-label="${safeListingText(x.name)}"><div class="card__head"><span class="treat-stop-number">${x.num}</span><div class="card__heading"><h3 class="card__name">${safeListingText(x.name)}</h3><span class="card__town">${safeListingText(x.town)}</span>${distanceLabelHTML(x)}${typeof openTonightBadgeHTML==='function'?openTonightBadgeHTML(x,{eligible:openTonightOK}):''}</div></div>${listingStatusHTML(x)}<div class="card__body"><p>${safeListingText(x.address)}</p><p>${safeListingText([x.dates,compactTime(x.times)].filter(Boolean).join(' · ')||((typeof hasScheduleInfo==='function'&&hasScheduleInfo(x))?'Candy hours not specified':'Hours unknown'))}</p></div><div class="chips">${x.features.map(v=>`<span class="chip">${safeListingText(v)}</span>`).join('')}</div>${x.notes?`<details class="card__notes"><summary>Read host notes</summary><div>${safeListingText(x.notes)}</div></details>`:''}<div class="card__actions"><button class="btn btn--route" type="button" data-route="${x.num}" aria-pressed="${onRoute}">${onRoute?'Added ✓':'+ Add to Route'}</button><a class="btn btn--directions" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener">Directions ↗</a><button class="btn card__fav-btn" type="button" data-fav="${x.num}" aria-pressed="${state.favorites.some(f=>f.num===x.num)}" aria-label="${state.favorites.some(f=>f.num===x.num)?`Remove #${x.num} from favorites`:`Save #${x.num} to favorites`}">${state.favorites.some(f=>f.num===x.num)?'♥':'♡'}</button></div><div class="card__extras"><button type="button" class="card-rating" data-feedback="${x.num}" data-rating-summary="${x.num}" aria-label="View ratings for ${safeListingText(x.name)}">No ratings yet</button><button type="button" class="btn--feedback" data-report-listing="${x.num}">Report / update</button><button type="button" class="btn--feedback" data-share-house="${x.num}">Share house</button></div>${listingUpdatedHTML(x)}</article>`}
function cardHTML(x){if(x.placeholder)return `<article class="card card--compact card--vacant" aria-label="Listing ${x.num} available"><div class="card__head"><span class="vacant-number">${x.num}</span><div class="card__heading"><h3 class="card__name">Listing number available</h3></div></div><div class="card__body"><p>This number is reserved for the next new listing.</p></div></article>`;if(isTreatStop(x))return treatCardHTML(x);const selected=state.selected===x.num,onRoute=state.route.some(r=>r.num===x.num);return `<article class="card card--compact ${selected?'is-selected':''}" data-card="${x.num}" tabindex="0" aria-label="${safeListingText(x.name)}"><div class="card__head"><div class="card__pin">${pinHTML(x.num)}</div><div class="card__heading"><h3 class="card__name">${safeListingText(x.name)}</h3><div class="card__subline"><span class="card__town">${safeListingText(x.town)}</span>${distanceLabelHTML(x)}${typeof openTonightBadgeHTML==='function'?openTonightBadgeHTML(x,{eligible:openTonightOK}):''}<span class="card__scare">${scarePips(x.levels)}</span></div></div></div>${listingStatusHTML(x)}<div class="card__body"><p>${safeListingText(x.address)}</p><p>${safeListingText([x.dates,compactTime(x.times)].filter(Boolean).join(' · ')||((typeof hasScheduleInfo==='function'&&hasScheduleInfo(x))?'Dates and hours not specified':'Hours unknown'))}</p></div><div class="card__tags">${x.type.map(t=>`<span class="chip chip--type">${safeListingText(t)}</span>`).join('')}<div class="chips">${x.features.map(featureChip).join('')}</div></div><details class="card__notes"><summary>Read host notes</summary><div>${safeListingText(x.notes||'No additional notes yet.')}</div></details><div class="card__actions"><button class="btn btn--route" type="button" data-route="${x.num}" aria-pressed="${onRoute}">${onRoute?'Added ✓':'+ Add to Route'}</button><a class="btn btn--directions" href="${gmapsDirections(x.address)}" target="_blank" rel="noopener">Directions ↗</a><button class="btn card__fav-btn" type="button" data-fav="${x.num}" aria-pressed="${state.favorites.some(f=>f.num===x.num)}" aria-label="${state.favorites.some(f=>f.num===x.num)?`Remove #${x.num} from favorites`:`Save #${x.num} to favorites`}">${state.favorites.some(f=>f.num===x.num)?'♥':'♡'}</button></div><div class="card__extras"><button type="button" class="card-rating" data-feedback="${x.num}" data-rating-summary="${x.num}" aria-label="View ratings for ${safeListingText(x.name)}">No ratings yet</button><button type="button" class="btn--feedback" data-report-listing="${x.num}">Report / update</button><button type="button" class="btn--feedback" data-share-house="${x.num}">Share house</button></div>${listingUpdatedHTML(x)}</article>`}

function dateFilterChipsHTML(){
 const f=state.dateFilter||{};
 const chip=(kind,label)=>`<button type="button" class="filter filter--date" data-date-filter="${kind}" aria-pressed="${f.kind===kind}">${label}</button>`;
 const dateInput=f.kind==='date'?`<input type="date" id="dateFilterInput" class="filter-date-input" value="${safeListingText(f.date||'')}" aria-label="Choose a date">`:'';
 return `<div class="filter-tier filter-tier--date"><span class="filterbar__label">When</span>${chip('tonight','Tonight')}${chip('weekend','This weekend')}${chip('date','Choose a date')}${dateInput}</div>`;
}
function renderFilters(){const button=f=>`<button class="filter ${FEATURE_ICONS[f]?'filter--feature':''}" type="button" data-filter="${f}" aria-pressed="${state.filter===f}">${featureIcon(f)}${safeListingText(FEATURE_ICONS[f]?.label||f)}</button>`;const featureActive=filters.some(f=>FEATURE_ICONS[f]&&state.filter===f),anyActive=state.filter!=='All'||Boolean(state.dateFilter&&state.dateFilter.kind);document.getElementById('filters').innerHTML=`<div class="filter-tier filter-tier--primary"><span class="filterbar__label">Show</span>${filters.filter(f=>!FEATURE_ICONS[f]).map(button).join('')}${anyActive?'<button class="filter filter--reset" type="button" data-reset-filters>Reset filters</button>':''}</div><details class="filter-tier filter-tier--features"${featureActive?' open':''}><summary>Features</summary>${filters.filter(f=>FEATURE_ICONS[f]).map(button).join('')}</details>${dateFilterChipsHTML()}`}

function renderCards(){const visible=activeListings();openTonightOK=typeof openTonightEligible==='function'&&typeof todayParts==='function'?openTonightEligible(visible,todayParts().dateStr):false;state.page=Math.max(0,Math.min(state.page,Math.ceil(visible.length/3)-1));const geoEmpty=typeof geoEmptyState==='function'?geoEmptyState():null,noResults=document.getElementById('noResults'),nonPlaceholder=visible.filter(x=>!x.placeholder);noResults.dataset.mode=(!visible.length&&geoEmpty)?'geo':'';const noun=state.category==='treats'?'treat stop':'display',dateLabel=typeof dateFilterLabel==='function'?dateFilterLabel(state.dateFilter):null;document.getElementById('countLine').textContent=(state.search?`${nonPlaceholder.length} ${noun}${nonPlaceholder.length===1?'':'s'} within ${state.search.radius} mi`:`${nonPlaceholder.length} ${noun}${visible.length===1?'':'s'} shown`)+(state.filter!=='All'?' · '+state.filter:'')+(dateLabel?' · '+dateLabel:'');document.getElementById('cardList').innerHTML=visible.slice(state.page*3,state.page*3+3).map(cardHTML).join('');noResults.classList.toggle('is-hidden',visible.length>0);const actionBtn=document.getElementById('emptyActionBtn');if(!visible.length&&geoEmpty){noResults.querySelector('strong').textContent=geoEmpty.headline;document.getElementById('noResultsText').textContent='';wireEmptyAction(geoEmpty,state.category==='treats'?'https://forms.gle/DTuKs27nSUWVbyf1A':FORM_URL)}else{document.getElementById('noResultsText').textContent=`No displays match “${state.filter}” right now.`;if(actionBtn)actionBtn.hidden=true}markerByNum.forEach((m,n)=>{const x=listings.find(v=>v.num===n);if(x&&matchFilter(x))m.addTo(map);else map.removeLayer(m)});syncEventPins();wireCards()}
function wireCards(){document.querySelectorAll('[data-card]').forEach(card=>{const n=+card.dataset.card;card.addEventListener('click',e=>{if(e.target.closest('button,a,details'))return;selectListing(n,true)});card.addEventListener('keydown',e=>{if(e.target!==card||!['Enter',' '].includes(e.key))return;e.preventDefault();selectListing(n,true)});card.addEventListener('mouseenter',()=>linkPair(n,true));card.addEventListener('mouseleave',()=>linkPair(n,false));card.addEventListener('focus',()=>linkPair(n,true));card.addEventListener('blur',()=>linkPair(n,false))});document.querySelectorAll('[data-route]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleRoute(+b.dataset.route)});document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFavorite(+b.dataset.fav)})}
function linkPair(n,on){if(matchMedia('(pointer:fine)').matches){document.querySelector(`[data-card="${n}"]`)?.classList.toggle('is-linked',on);markerByNum.get(n)?.getElement()?.querySelector('.pin')?.classList.toggle('is-linked',on)}}
function selectListing(n,scroll=false){if(listings.find(x=>x.num===n)?.placeholder)return;state.selected=n;markerByNum.forEach((m,num)=>m.getElement()?.querySelector('.pin')?.classList.toggle('is-selected',num===n));document.querySelectorAll('[data-card]').forEach(c=>c.classList.toggle('is-selected',+c.dataset.card===n));renderPeek(n);if(scroll&&innerWidth<1024)document.querySelector(`[data-card="${n}"]`)?.scrollIntoView({behavior:'smooth',block:'center'})}
function renderPeek(n){const x=listings.find(v=>v.num===n);if(!x||!matchFilter(x)){document.getElementById('mapPeek').classList.add('is-hidden');return}const onRoute=state.route.some(r=>r.num===n),peek=document.getElementById('mapPeek');peek.innerHTML=`<div class="card__pin">${pinHTML(x.num)}</div><div class="map-peek__meta"><strong>${safeListingText(x.name)}</strong><small>${safeListingText(x.town)}${x.times?' · '+safeListingText(x.times):''}</small></div><button class="btn btn--route" type="button" data-peek-route="${n}" aria-pressed="${onRoute}">${onRoute?'Added ✓':'+ Add'}</button><button class="btn card__fav-btn map-peek__fav" type="button" data-peek-fav="${n}" aria-pressed="${state.favorites.some(f=>f.num===n)}" aria-label="${state.favorites.some(f=>f.num===n)?`Remove #${n} from favorites`:`Save #${n} to favorites`}">${state.favorites.some(f=>f.num===n)?'♥':'♡'}</button>`;peek.classList.remove('is-hidden');typeof loadPeekPhotos==='function'&&loadPeekPhotos(n,x);peek.querySelector('[data-peek-route]').onclick=()=>toggleRoute(n);peek.querySelector('[data-peek-fav]').onclick=e=>{e.stopPropagation();toggleFavorite(n)}}
function toggleRoute(n){const listing=listings.find(x=>x.num===n);if(!listing||listing.placeholder)return;state.routeMessage='';const had=state.route.length;state.route=state.route.some(r=>r.num===n)?state.route.filter(r=>r.num!==n):[...state.route,{num:n,entityId:listing.entityId}];if(state.route.length>had)setRouteExpanded(true,false);try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderCards();renderRoute();renderPeek(state.selected);markerByNum.forEach((m,num)=>m.getElement()?.querySelector('.pin')?.classList.toggle('is-on-route',state.route.some(r=>r.num===num)))}
// v5 Phase F: events join the shared route with a discriminated {eventId}
// entry (see routing.js). Same toggle pattern as listings; no map pins for
// events, so only the planner and cards re-render.
function toggleEventRoute(eventId){const ev=events.find(x=>x.id===eventId);if(!ev)return;state.routeMessage='';const had=state.route.length;state.route=toggleRouteEntry(state.route,{eventId:ev.id});if(state.route.length>had)setRouteExpanded(true,false);try{localStorage.setItem('hfroute:2026',JSON.stringify(state.route))}catch{}renderRoute();renderCards()}

function toggleFavorite(n){const listing=listings.find(x=>x.num===n);if(!listing||listing.placeholder)return;state.favorites=toggleFavoriteEntry(state.favorites,n,listing.entityId);try{localStorage.setItem('hffavs:v1',JSON.stringify(state.favorites))}catch{}renderCards();renderPeek(state.selected)}
let routeExpanded=false;
function setRouteExpanded(open,focus){routeExpanded=open;const t=document.getElementById('routeToggle'),r=document.getElementById('routeRegion');if(!t||!r)return;t.setAttribute('aria-expanded',String(open));r.hidden=!open;const hint=document.getElementById('routeToggleHint');if(hint)hint.textContent=open?'Collapse':'Expand';if(focus){if(open){const f=r.querySelector('button,input');f&&f.focus()}else t.focus()}}
function openRouteSheet(){renderRoute();const s=document.getElementById('routeSheet');if(s&&typeof s.showModal==='function')s.showModal()}
document.getElementById('routeToggle').onclick=()=>setRouteExpanded(!routeExpanded,true);
function renderRoute(){const sheetBadge=document.getElementById('routeSheetBadge');if(sheetBadge)sheetBadge.textContent=state.route.length;document.getElementById('mobileRouteBar').classList.toggle('is-hidden',!state.route.length);document.getElementById('mobileMapRouteBtn').disabled=!state.route.length;document.getElementById('mobileRouteCount').textContent=`${state.route.length} stop${state.route.length===1?'':'s'} selected`;const present=state.route.map(r=>r.eventId!=null?{...events.find(x=>x.id===r.eventId),isEvent:true}:listings.find(x=>x.num===r.num)).filter(Boolean);const flagByNum=new Map();if(typeof stopsWithAreaFlags==='function')stopsWithAreaFlags(present.filter(s=>!s.isEvent),state.search).forEach(s=>flagByNum.set(s.num,s.outOfArea));const stops=present.map(s=>s.isEvent?{...s,outOfArea:false}:{...s,outOfArea:Boolean(flagByNum.get(s.num))});const planner=document.getElementById('routePlanner'),sheetBody=document.getElementById('routeSheetBody'),plannerTargets=[planner,sheetBody].filter(Boolean),html=`<div class="route__setup"><p class="route__helper">Add displays, treat stops, or events to your route. Move stops up or down, or suggest an order before opening Google Maps.</p><div class="route__starting"><div class="route__label">Starting from</div><div class="seg" role="radiogroup" aria-label="Starting point"><button type="button" data-mode="current" aria-checked="${state.startMode==='current'}">My location</button><button type="button" data-mode="address" aria-checked="${state.startMode==='address'}">Enter address</button></div>${state.startMode==='current'?`<div class="current-note" style="margin-top:10px"><span class="current-dot"></span>Google Maps uses your location when you open directions</div>`:`<input class="route__input" id="startAddr" value="${safeListingText(state.startAddr)}" placeholder="Enter your starting address" style="margin-top:10px">`}</div></div><div class="route__stops-band"><div class="route__stops-head"><div class="route__label">Your stops (${stops.length})</div><button class="btn btn--outline" id="optimizeRouteBtn" title="Keeps your first stop and suggests an order by straight-line distance" type="button" ${stops.length<2||state.optimizing?'disabled':''}>${state.optimizing?'Finding order…':'Suggest order'}</button><button class="btn btn--outline" id="shareOutingBtn" type="button" ${stops.length?'':'disabled'}>Share outing</button></div><div class="stops" style="margin-top:8px">${stops.length?stops.map((s,i)=>`<div class="stop"><span class="stop__order">${i+1}</span><div class="stop__meta"><strong>${safeListingText(s.name)}</strong><small>${s.isEvent?safeListingText(eventStopDateLine(s)):safeListingText(s.town)}${s.outOfArea?' · Outside your current search area':''}</small></div><div class="stop__controls"><button type="button" data-move-stop="${s.isEvent?'e:'+s.id:'n:'+s.num}" data-direction="-1" ${i===0||state.optimizing?'disabled':''} aria-label="Move ${safeListingText(s.name)} earlier">↑</button><button type="button" data-move-stop="${s.isEvent?'e:'+s.id:'n:'+s.num}" data-direction="1" ${i===stops.length-1||state.optimizing?'disabled':''} aria-label="Move ${safeListingText(s.name)} later">↓</button><button type="button" class="stop__remove" data-remove="${s.isEvent?'e:'+s.id:'n:'+s.num}" aria-label="Remove ${safeListingText(s.name)}">×</button></div></div>`).join(''):`<div class="empty"><strong>No stops yet</strong><span>Add a display, treat stop, or event to start planning your route.</span></div>`}</div></div><div class="route__action"><p id="routeOrderStatus" role="status">${safeListingText(state.routeMessage||'')}</p><p class="route__handoff">Opens driving directions in Google Maps (up to 10 stops). Suggested order keeps your first stop and uses straight-line distance. Check roads and hours; mobile browsers may limit stops.</p><button class="btn btn--map-route" id="mapRouteBtn" type="button" aria-disabled="${stops.length===0}" style="margin-top:4px">Map My Route</button></div>`;plannerTargets.forEach(planner=>{planner.innerHTML=html;planner.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.startMode=b.dataset.mode;state.startCoords=null;state.routeMessage='';renderRoute()});planner.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const v=b.dataset.remove;if(v.startsWith('e:')){state.routeMessage='';toggleEventRoute(v.slice(2))}else{state.routeMessage='';toggleRoute(+v)}});planner.querySelectorAll('[data-move-stop]').forEach(b=>b.onclick=()=>moveRouteStop(b.dataset.moveStop,+b.dataset.direction));planner.querySelector('#startAddr')?.addEventListener('input',e=>{state.startAddr=e.target.value;state.startCoords=null;state.routeMessage=''});planner.querySelector('#mapRouteBtn').onclick=buildRoute;planner.querySelector('#optimizeRouteBtn').onclick=optimizeRoute;planner.querySelector('#shareOutingBtn').onclick=shareOuting})}
async function shareOuting(){if(!state.route.length)return;const link=outingLink(state.route);try{await navigator.clipboard.writeText(link);state.routeMessage='Outing link copied — send it to friends.'}catch(e){state.routeMessage='Copy this link: '+link}renderRoute()}

function buildRoute(){const stops=state.route.map(r=>r.eventId!=null?events.find(x=>x.id===r.eventId):listings.find(x=>x.num===r.num)).filter(Boolean);if(!stops.length)return;if(stops.length>10){state.routeMessage='Google Maps supports up to 10 stops here. Split this into smaller routes.';renderRoute();return}const capped=stops.slice(0,10),last=capped.at(-1),wps=capped.slice(0,-1).map(x=>x.address).join('|');const p=new URLSearchParams({api:'1',travelmode:'driving',destination:last.address});if(wps)p.set('waypoints',wps);if(state.startMode==='address'&&state.startAddr.trim())p.set('origin',state.startAddr.trim());else if(state.startCoords)p.set('origin',state.startCoords.lat+','+state.startCoords.lng);window.open(`https://www.google.com/maps/dir/?${p.toString()}`,'_blank','noopener')}

async function loadMarkers(){const bounds=[];for(const x of listings){if(x.placeholder||!Number.isFinite(x.lat)||!Number.isFinite(x.lng))continue;const c={lat:x.lat,lng:x.lng};state.coords[x.num]=c;const m=L.marker([c.lat,c.lng],{icon:iconFor(x.num),keyboard:true,title:`Display ${x.num}: ${x.name}`,zIndexOffset:(listings.filter(v=>v.address===x.address).length>1?1000:100)+x.num}).addTo(map);m.on('click',()=>{selectListing(x.num,true)});m.on('mouseover',()=>linkPair(x.num,true));m.on('mouseout',()=>linkPair(x.num,false));markerByNum.set(x.num,m);bounds.push([c.lat,c.lng])}if(bounds.length)map.fitBounds(bounds,{paddingTopLeft:[40,80],paddingBottomRight:[40,40]});setTimeout(()=>map.invalidateSize(),100)}

document.getElementById('filters').addEventListener('click',e=>{if(e.target.closest('[data-reset-filters]')){state.filter='All';state.dateFilter=typeof saveDateFilter==='function'?saveDateFilter({kind:null,date:null},localStorage):null;state.page=0;renderFilters();renderCards();return}const b=e.target.closest('[data-filter]');if(!b)return;state.filter=state.filter===b.dataset.filter?'All':b.dataset.filter;renderFilters();renderCards()});document.getElementById('showAllBtn').onclick=()=>{state.filter='All';renderFilters();renderCards()};document.getElementById('shareBtn').onclick=async()=>{const b=document.getElementById('shareBtn'),payload={title:'Hauntfinder',text:'Find Halloween displays, treat stops, and events near you.',url:'https://hauntfinder.vercel.app/'};try{if(navigator.share)await navigator.share(payload);else{await navigator.clipboard.writeText('https://hauntfinder.vercel.app/');b.textContent='Link copied';setTimeout(()=>b.textContent='Share this site',2000)}}catch{}};
renderFilters();renderCards();renderRoute();loadMarkers();


